import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.BjkiRu3Q.js";const u=JSON.parse('{"title":"Authentication and tenant access","description":"","frontmatter":{},"headers":[],"relativePath":"developers/authentication.md","filePath":"developers/authentication.md"}'),r={name:"developers/authentication.md"};function i(s,e,d,c,p,l){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="authentication-and-tenant-access" tabindex="-1">Authentication and tenant access <a class="header-anchor" href="#authentication-and-tenant-access" aria-label="Permalink to &quot;Authentication and tenant access&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Source-reviewed draft · v0.7.9 reference. Confirm availability and permissions against the approved target release.</p></div><h2 id="operator-api-contract" tabindex="-1">Operator API contract <a class="header-anchor" href="#operator-api-contract" aria-label="Permalink to &quot;Operator API contract&quot;">​</a></h2><p>Protected operator routes are mounted under <code>/api/v1</code>. Send a valid bearer access token in <code>Authorization</code> and the selected company UUID in <code>X-Company-Id</code>. The server verifies membership and permission independently; the company header does not grant access.</p><p>The source uses RS256 JWT verification. Use the approved authentication flow for the target environment; never embed operator tokens in a public storefront or widget.</p><table tabindex="0"><thead><tr><th>Response</th><th>Meaning</th></tr></thead><tbody><tr><td>401</td><td>Missing or invalid token</td></tr><tr><td>400</td><td>Missing or invalid company selection</td></tr><tr><td>403</td><td>Tenant or permission denied</td></tr><tr><td>503</td><td>Authorization unavailable</td></tr></tbody></table><p>On a denial, resolve the underlying access issue rather than substituting another company&#39;s ID. Use only synthetic data in integration tests.</p><p>See <a href="/developers/permissions.html">Roles and permissions</a>.</p><p>For provider credentials see <a href="/integrations/api-keys.html">API keys &amp; secure setup</a>.</p>',9)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
